"use client";

import {
    Wallet,
    ArrowUpRight,
    ArrowDownCircle,
    Download,
    Clock,
    CheckCircle2,
    Search,
    TrendingUp,
    CreditCard,
    Banknote,
    Calendar,
    Filter,
    XCircle,
    AlertCircle
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useState } from "react";
import { useSimulation } from "@/components/SimulationProvider";
import useSWR, { useSWRConfig } from "swr";
import { fetcher } from "@/lib/fetcher";
import Modal from "@/components/Modal";
import Input from "@/components/ui/Input";
import axios from "axios";

export default function FinanceiroPage() {
    const { currentUser } = useSimulation();
    const { mutate } = useSWRConfig();
    const { data: financialData, isLoading, error } = useSWR(
        currentUser?.id ? `/api/financials?userId=${currentUser.id}` : null,
        fetcher
    );

    const [isWithdrawModalOpen, setIsWithdrawModalOpen] = useState(false);
    const [withdrawAmount, setWithdrawAmount] = useState("");
    const [pixKey, setPixKey] = useState(currentUser?.pix_key || "");
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [formError, setFormError] = useState("");

    const handleWithdrawRequest = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);
        setFormError("");

        if (Number(withdrawAmount) > financialData.available) {
            setFormError("Saldo disponível insuficiente.");
            setIsSubmitting(false);
            return;
        }

        try {
            await axios.post("/api/financials", {
                userId: currentUser.id,
                amount: Number(withdrawAmount),
                pixKey: pixKey
            });

            mutate(`/api/financials?userId=${currentUser.id}`);
            setIsWithdrawModalOpen(false);
            setWithdrawAmount("");
        } catch (err: any) {
            setFormError(err.response?.data?.error || "Erro ao processar solicitação.");
        } finally {
            setIsSubmitting(false);
        }
    };

    if (isLoading) return <div className="p-8 text-center animate-pulse font-bold text-slate-400">CARREGANDO DADOS FINANCEIROS...</div>;

    const transactions = financialData?.transactions || [];

    return (
        <div className="p-4 lg:p-8 space-y-8">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-black mb-1">Módulo Financeiro</h1>
                    <p className="text-xs text-slate-500 font-medium uppercase tracking-wider">Gestão de Repasses e Margem de Intermediação</p>
                </div>
                <button
                    onClick={() => setIsWithdrawModalOpen(true)}
                    className="bg-primary text-white px-6 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 shadow-lg shadow-primary/20 hover:scale-[1.02] transition-all self-start md:self-auto"
                >
                    <ArrowDownCircle size={16} />
                    Solicitar Saque (PIX)
                </button>
            </div>

            {/* Balance Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm overflow-hidden relative group">
                    <div className="relative z-10">
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Saldo Disponível (Repasses)</p>
                        <h4 className="text-3xl font-black mb-4">
                            {financialData?.available.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                        </h4>
                        <div className="flex items-center gap-2 text-xs font-bold text-emerald-500">
                            <TrendingUp size={14} />
                            <span>Valor pronto para retirada</span>
                        </div>
                    </div>
                    <Wallet className="absolute -bottom-4 -right-4 size-32 text-slate-50 dark:text-slate-700/50 group-hover:text-primary/5 transition-colors -z-0" />
                </div>

                <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm overflow-hidden relative group">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Saldo em Processamento</p>
                    <h4 className="text-3xl font-black mb-4 text-amber-500">
                        {financialData?.processing.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                    </h4>
                    <div className="flex items-center gap-2 text-xs font-bold text-slate-400">
                        <Clock size={14} />
                        <span>Aguardando liquidação manual</span>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Total Liquidado</p>
                    <h4 className="text-3xl font-black mb-4">
                        {financialData?.withdrawn.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                    </h4>
                    <div className="flex items-center gap-2 text-xs font-bold text-indigo-500">
                        <CheckCircle2 size={14} />
                        <span>Histórico de transferências</span>
                    </div>
                </div>
            </div>

            {/* Transaction History */}
            <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
                <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                    <h3 className="text-lg font-bold">Extrato de Repasses</h3>
                    <button className="flex items-center gap-2 text-xs font-bold text-primary hover:underline">
                        <Download size={14} />
                        Exportar CSV
                    </button>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-50/50 dark:bg-white/5 border-b border-slate-100 dark:border-slate-800">
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Tipo / Descrição</th>
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Data e Hora</th>
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Status</th>
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 text-right">Valor</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
                            {transactions.length === 0 && (
                                <tr>
                                    <td colSpan={4} className="px-6 py-10 text-center text-slate-400 text-xs font-bold font-mono">NENHUM LANÇAMENTO ENCONTRADO</td>
                                </tr>
                            )}
                            {transactions.map((tx: any) => (
                                <tr key={tx.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-900/50 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-3">
                                            <div className={cn(
                                                "size-9 rounded-xl flex items-center justify-center",
                                                Number(tx.amount) > 0 ? "bg-emerald-50 text-emerald-600 dark:bg-emerald-900/20" : "bg-rose-50 text-rose-600 dark:bg-rose-900/20"
                                            )}>
                                                {Number(tx.amount) > 0 ? <Banknote size={18} /> : <CreditCard size={18} />}
                                            </div>
                                            <div>
                                                <p className="text-sm font-bold text-slate-900 dark:text-white">{tx.type}</p>
                                                <p className="text-[10px] text-slate-500 font-medium">{tx.description}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2 text-slate-500">
                                            <Calendar size={14} />
                                            <span className="text-xs font-medium">
                                                {new Date(tx.created_at).toLocaleString('pt-BR')}
                                            </span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={cn(
                                            "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold ring-1 ring-inset",
                                            tx.status === 'Disponível' ? "bg-emerald-50 text-emerald-700 ring-emerald-600/20" :
                                                tx.status === 'Liquidado' ? "bg-blue-50 text-blue-700 ring-blue-600/20" :
                                                    tx.status === 'Processando' ? "bg-amber-50 text-amber-700 ring-amber-600/20" :
                                                        "bg-rose-50 text-rose-700 ring-rose-600/20"
                                        )}>
                                            {tx.status}
                                        </span>
                                    </td>
                                    <td className={cn(
                                        "px-6 py-4 text-right text-sm font-black",
                                        Number(tx.amount) > 0 ? "text-emerald-500" : "text-rose-500"
                                    )}>
                                        {(Number(tx.amount) > 0 ? "+" : "") + Number(tx.amount).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Withdraw Modal */}
            <Modal
                isOpen={isWithdrawModalOpen}
                onClose={() => setIsWithdrawModalOpen(false)}
                title="Solicitar Saque Total (Repasse)"
                width="sm"
            >
                <form onSubmit={handleWithdrawRequest} className="space-y-6">
                    <div className="bg-slate-50 dark:bg-slate-900 p-5 rounded-2xl border border-slate-100 dark:border-slate-800 space-y-1">
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Saldo Disponível p/ Resgate</p>
                        <p className="text-3xl font-black text-emerald-500">
                            {financialData?.available.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                        </p>
                        <p className="text-[9px] text-slate-500 font-medium">Atenção: O saque será realizado sobre o valor total disponível.</p>
                    </div>

                    <div className="space-y-4">
                        <div className="relative">
                            <Input
                                label="Valor do Saque (Total)"
                                type="text"
                                value={financialData?.available.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                                readOnly
                                className="bg-slate-50 border-dashed opacity-80 cursor-not-allowed font-bold"
                            />
                            <div className="absolute right-3 top-[34px]">
                                <CheckCircle2 size={16} className="text-emerald-500" />
                            </div>
                        </div>
                        <Input
                            label="Chave PIX para Recebimento"
                            value={pixKey}
                            onChange={(e: any) => setPixKey(e.target.value)}
                            placeholder="CPF, E-mail, Celular ou Aleatória"
                            required
                        />
                    </div>

                    {formError && (
                        <div className="flex items-center gap-2 text-rose-500 text-xs font-bold bg-rose-50 dark:bg-rose-900/20 p-3 rounded-xl border border-rose-100 dark:border-rose-900/30">
                            <AlertCircle size={14} />
                            <span>{formError}</span>
                        </div>
                    )}

                    <div className="flex flex-col gap-3">
                        <button
                            type="submit"
                            disabled={isSubmitting || (financialData?.available || 0) <= 0}
                            className="w-full bg-primary text-white py-3.5 rounded-xl font-bold text-sm shadow-xl shadow-primary/20 hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50"
                        >
                            {isSubmitting ? "Processando..." : `Confirmar Resgate de ${(financialData?.available || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`}
                        </button>
                        <button
                            type="button"
                            onClick={() => setIsWithdrawModalOpen(false)}
                            className="w-full text-slate-400 font-bold text-xs uppercase tracking-widest hover:text-slate-600 transition-colors"
                        >
                            Cancelar
                        </button>
                    </div>
                </form>
            </Modal>
        </div>
    );
}
